package org.apache.commons.math3.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.FieldElement;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Complex_abs_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testAbs_NaN() {
        Complex c = new Complex(Double.NaN, 1.0);
        assertEquals(Double.NaN, c.abs(), 0.0);

        Complex c2 = new Complex(1.0, Double.NaN);
        assertEquals(Double.NaN, c2.abs(), 0.0);
    }

    @Test
    public void testAbs_Infinite() {
        Complex c = new Complex(Double.POSITIVE_INFINITY, 1.0);
        assertEquals(Double.POSITIVE_INFINITY, c.abs(), 0.0);

        Complex c2 = new Complex(1.0, Double.NEGATIVE_INFINITY);
        assertEquals(Double.POSITIVE_INFINITY, c2.abs(), 0.0);
    }

    @Test
    public void testAbs_RealSmallerThanImaginary_ImaginaryZero() {
        // This branch is technically unreachable if real < abs(imaginary) and imaginary == 0,
        // because if imaginary is 0, then abs(imaginary) is 0, 
        // and abs(real) < 0 is impossible for real numbers.
        // However, we test the logic of the 'else' block for real/imaginary comparisons.
        Complex c = new Complex(3.0, 0.0);
        assertEquals(3.0, c.abs(), EPSILON);
    }

    @Test
    public void testAbs_RealSmallerThanImaginary_General() {
        // Path: abs(real) < abs(imaginary)
        // real = 3, imag = 4 -> abs = 5
        Complex c = new Complex(3.0, 4.0);
        assertEquals(5.0, c.abs(), EPSILON);

        // Path: real = -3, imag = 4 -> abs = 5
        Complex c2 = new Complex(-3.0, 4.0);
        assertEquals(5.0, c2.abs(), EPSILON);
    }

    @Test
    public void testAbs_ImaginarySmallerThanReal_RealZero() {
        // Path: abs(real) >= abs(imaginary) AND real == 0.0
        // Note: If real is 0, then abs(0) < abs(imaginary) would usually trigger the first block
        // unless imaginary is also 0.
        Complex c = new Complex(0.0, 5.0);
        // In the provided code: if (0 < 5) { if (5 == 0) ... else { q = 0/5; return 5 * sqrt(1+0) } }
        // This actually hits the first block. To hit the second block's "real == 0.0", 
        // we need the first condition (abs(real) < abs(imaginary)) to be false.
        // This happens if real is non-zero and abs(real) >= abs(imaginary).
        // Actually, the only way to hit the second block's `real == 0.0` is if the first `if` is false.
        // If real == 0, then abs(real) is 0. 0 < abs(imaginary) is true unless imaginary is 0.
        // If imaginary is 0 and real is 0, it hits the first block's imaginary == 0 check.
        // Therefore, the 'real == 0.0' in the second block is likely dead code or for edge cases.
        // We will test the standard path for the second block.
    }

    @Test
    public void testAbs_ImaginarySmallerThanReal_General() {
        // Path: abs(real) >= abs(imaginary)
        // real = 4, imag = 3 -> abs = 5
        Complex c = new Complex(4.0, 3.0);
        assertEquals(5.0, c.abs(), EPSILON);

        // real = 4, imag = -3 -> abs = 5
        Complex c2 = new Complex(4.0, -3.0);
        assertEquals(5.0, c2.abs(), EPSILON);
    }

    @Test
    public void testAbs_Zero() {
        Complex c = new Complex(0.0, 0.0);
        assertEquals(0.0, c.abs(), EPSILON);
    }

    @Test
    public void testAbs_LargeValues() {
        // Test to ensure no overflow during q*q if possible, 
        // though the formula is designed to prevent it.
        double large = 1e150;
        Complex c = new Complex(large, large);
        // sqrt(large^2 + large^2) = large * sqrt(2)
        assertEquals(large * Math.sqrt(2.0), c.abs(), 1e140);
    }
}
